import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int MAXR = 11;
    static final int MAXN = 1000;
    static final int MAXM = 100100;
    static final int oo = 1 << 29;

    static int[] ady = new int[2 * MAXM];
    static int[] flow = new int[2 * MAXM];
    static int[] cap = new int[2 * MAXM];
    static int[] nxt = new int[2 * MAXM];
    static int[] last = new int[MAXN + 1];
    static int[] now = new int[MAXN + 1];
    static int[] lev = new int[MAXN + 1];
    static int[] cola = new int[MAXN + 1];

    static int E, n, s, t;

    static void initFlow(int nn, int ss, int tt) {
        n = nn;
        s = ss;
        t = tt;
        E = 2;
        Arrays.fill(last, 0);
    }

    static void addEdge(int u, int v, int c) {
        ady[E] = v;
        flow[E] = 0;
        cap[E] = c;
        nxt[E] = last[u];
        last[u] = E++;
        ady[E] = u;
        flow[E] = 0;
        cap[E] = 0;
        nxt[E] = last[v];
        last[v] = E++;
    }

    static boolean bfs() {
        Arrays.fill(lev, 0);
        int enq = 0, deq = 0;
        cola[enq++] = s;
        lev[s] = 1;
        while (deq < enq && lev[t] == 0) {
            int u = cola[deq++];
            for (int e = last[u]; e != 0; e = nxt[e]) {
                int v = ady[e];
                if (lev[v] == 0 && flow[e] < cap[e]) {
                    lev[v] = lev[u] + 1;
                    cola[enq++] = v;
                }
            }
        }
        return lev[t] != 0;
    }

    static int dfs(int u, int F) {
        if (u == t) return F;
        for (int e = now[u]; e != 0; e = now[u] = nxt[e]) {
            int v = ady[e];
            if (lev[u] < lev[v] && flow[e] < cap[e]) {
                int f = dfs(v, Math.min(F, cap[e] - flow[e]));
                if (f > 0) {
                    flow[e] += f;
                    flow[e ^ 1] -= f;
                    return f;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int totalFlow = 0;
        while (bfs()) {
            for (int i = 0; i <= n; i++) {
                now[i] = last[i];
            }
            int f;
            while ((f = dfs(s, oo)) > 0) {
                totalFlow += f;
            }
        }
        return totalFlow;
    }

    static int R;
    static String[] m1 = new String[MAXR];
    static String[] m2 = new String[MAXR];

    static int[] movI = {0, 1, 0, -1};
    static int[] movJ = {1, 0, -1, 0};

    static boolean canMove(int i, int j, int R, String[] grid) {
        return (i >= 0 && j >= 0 && i < R && j < R && grid[i].charAt(j) != 'Y' && grid[i].charAt(j) != 'Z');
    }

    static int[][][] tim = new int[2][MAXR][MAXR];
    static int[][][] nod = new int[2][MAXR][MAXR];

    static void bfs2(int i, int j, int cc, int R, String[] grid) {
        for (int k = 0; k < R; k++) {
            for (int l = 0; l < R; l++) {
                tim[cc][k][l] = 0;
            }
        }
        tim[cc][i][j] = 1;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{i, j});
        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int ci = pos[0], cj = pos[1];
            if (cc == 1 && (tim[0][ci][cj] != 0 && tim[0][ci][cj] <= tim[1][ci][cj])) continue;
            for (int k = 0; k < 4; k++) {
                int ii = ci + movI[k];
                int jj = cj + movJ[k];
                if (canMove(ii, jj, R, grid) && tim[cc][ii][jj] == 0) {
                    tim[cc][ii][jj] = tim[cc][ci][cj] + 1;
                    q.offer(new int[]{ii, jj});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        int T = Integer.parseInt(st.nextToken());

        int zi = 0, zj = 0;
        int nCount = 0, sNode = 0, tNode = 0;

        for (int i = 0; i < R; i++) {
            m1[i] = br.readLine();
        }
        for (int i = 0; i < R; i++) {
            m2[i] = br.readLine();
        }

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (m1[i].charAt(j) == 'Z') {
                    zi = i;
                    zj = j;
                } else if (m1[i].charAt(j) != 'Y') {
                    nCount++;
                    nod[0][i][j] = nCount;
                }
            }
        }

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (m2[i].charAt(j) != 'Y' && m2[i].charAt(j) != 'Z') {
                    nCount++;
                    nod[1][i][j] = nCount;
                }
            }
        }

        nCount++;
        sNode = 0;
        tNode = nCount;
        initFlow(nCount, sNode, tNode);

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (m1[i].charAt(j) != 'Z' && m1[i].charAt(j) != 'Y') {
                    addEdge(sNode, nod[0][i][j], m1[i].charAt(j) - '0');
                    addEdge(nod[1][i][j], tNode, m2[i].charAt(j) - '0');
                }
            }
        }

        bfs2(zi, zj, 0, R, m1);
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < R; j++) {
                if (m1[i].charAt(j) > '0' && m1[i].charAt(j) <= '9') {
                    bfs2(i, j, 1, R, m1);
                    for (int ii = 0; ii < R; ii++) {
                        for (int jj = 0; jj < R; jj++) {
                            if (m2[ii].charAt(jj) > '0' && m2[ii].charAt(jj) <= '9') {
                                if (tim[1][ii][jj] != 0 && (tim[0][ii][jj] == 0 || tim[0][ii][jj] >= tim[1][ii][jj]) && tim[1][ii][jj] - 1 <= T) {
                                    addEdge(nod[0][i][j], nod[1][ii][jj], oo);
                                }
                            }
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
    }
